insert into public.surplus_statutes (state, sale_kind, statute_citation, source_url, claim_window_days, window_starts_from, escheat_days, escheat_starts_from, escheat_destination, fee_cap_pct, assignment_permitted, recovery_permitted, published, verified_at, verified_by, notes)
values
 ('TX','tax_deed','Tex. Tax Code § 34.03, § 34.04','https://texas.public.law/statutes/tex._tax_code_section_34.04',730,'sale_date',730,'sale_date','Taxing units participating in the sale (pro rata, Tex. Tax Code 34.03(b))',null,true,true,false, now(), 'statute text read 2026-08-17 (texas.public.law 34.03/34.04)',
  'Excess proceeds are paid into the court that ordered the sale and held by the clerk for two years after the sale date. A claim is made by petition filed BEFORE the second anniversary of the sale (34.04(a)); after that window the clerk distributes the money to the taxing units, so it does NOT go to a state unclaimed-property program. Texas sets no statutory finder fee cap in Chapter 34, so fee_cap_pct is left null rather than guessed. published stays false until at least one TX county source is live: as of 2026-08-17 no multi-county aggregator exists (tax law firms publish sale schedules only) and the Tyler Odyssey per-county "Excess Proceeds From Tax Sale" report hosts are unreachable from our egress (direct TCP timeout, 403 through the residential proxy).'),
 ('SC','tax_deed','S.C. Code § 12-51-130','https://www.scstatehouse.gov/code/t12c051.php',null,null,1825,'sale_date','General fund of the county/municipal governing body (S.C. Code 12-51-130)',null,true,true,false, now(), 'statute text read 2026-08-17 (scstatehouse.gov Title 12 Ch. 51)',
  'Sale proceeds above taxes, assessments, penalties and costs are first applied to outstanding municipal tax liens; any remaining overage belongs to the owner of record immediately before the end of the redemption period and is "payable ninety days after execution of the deed unless a judicial action is instituted during that time by another claimant". If neither claimed nor assigned within five years of the public auction tax sale the overage escheats to the general fund of the governing body — that five years is escheat_days (1825). The statute expressly contemplates assignment, and sets no finder fee cap, so fee_cap_pct is null. published stays false until an SC county source is live: no multi-county aggregator exists, and the one confirmed machine-readable overage list (Orangeburg County) sits behind a Cloudflare bot challenge.')
on conflict do nothing;